# Tab completion for offroad-autonomy and the repository scripts, in PowerShell.
# Generated by scripts/generate_completions.py from the argparse parsers:
# regenerate it after changing an option instead of editing it.
#
#   . .\completions\offroad-autonomy.ps1    # add to $PROFILE to keep it
#
# Scripts complete after python, python3 or py. When nothing here applies the
# completer returns nothing, and PowerShell falls back to file names.

$offroadCompleter = {
    param($wordToComplete, $commandAst, $cursorPosition)

    $spec = @{
        'benchmark_display_padding.py' = @{
            Options = @('-h', '--help', '--out', '--iterations')
            Values = @{ '--out' = 'file'; '--iterations' = 'none' }
            Subcommands = @()
            Positional = $false
        }
        'benchmark_planning.py' = @{
            Options = @('-h', '--help', '--out', '--half-width-m')
            Values = @{ '--out' = 'file'; '--half-width-m' = 'none' }
            Subcommands = @()
            Positional = $false
        }
        'benchmark_postprocess.py' = @{
            Options = @('-h', '--help', '--baseline-root', '--labels', '--out')
            Values = @{ '--baseline-root' = 'file'; '--labels' = 'file'; '--out' = 'file' }
            Subcommands = @()
            Positional = $false
        }
        'benchmark_rgb.py' = @{
            Options = @('-h', '--help', '--config', '--images', '--labels', '--label-suffix', '--out', '--limit', '--input-size', '--working-size', '--weights', '--half', '--no-half', '--threshold', '--clahe', '--morphology', '--ema', '--render-ui', '--road-value', '--void-value', '--timestamp-scale', '--sequence-gap-s', '--warmup', '--planning')
            Values = @{ '--config' = 'file'; '--images' = 'file'; '--labels' = 'file'; '--label-suffix' = 'file'; '--out' = 'file'; '--limit' = 'none'; '--input-size' = 'none'; '--working-size' = 'none'; '--weights' = 'file'; '--threshold' = 'none'; '--road-value' = 'none'; '--void-value' = 'none'; '--timestamp-scale' = 'none'; '--sequence-gap-s' = 'none'; '--warmup' = 'none' }
            Subcommands = @()
            Positional = $false
        }
        'check_brake_hold.py' = @{
            Options = @('-h', '--help', '--config', '--reproduce-arcade', '--out')
            Values = @{ '--config' = 'file'; '--out' = 'file' }
            Subcommands = @()
            Positional = $false
        }
        'closed_loop_log.py' = @{
            Options = @('-h', '--help', '--config', '--seconds', '--out', '--snap-from', '--summary')
            Values = @{ '--config' = 'file'; '--seconds' = 'none'; '--out' = 'file'; '--snap-from' = 'none' }
            Subcommands = @()
            Positional = $false
        }
        'compare_benchmarks.py' = @{
            Options = @('-h', '--help', '--markdown')
            Values = @{  }
            Subcommands = @()
            Positional = $true
        }
        'compare_control_logs.py' = @{
            Options = @('-h', '--help', '--out')
            Values = @{ '--out' = 'file' }
            Subcommands = @()
            Positional = $true
        }
        'derive_ego_mask.py' = @{
            Options = @('-h', '--help', '--config', '--margin-px', '--epsilon', '--close-px')
            Values = @{ '--config' = 'file'; '--margin-px' = 'none'; '--epsilon' = 'none'; '--close-px' = 'none' }
            Subcommands = @()
            Positional = $false
        }
        'diagnose_perception.py' = @{
            Options = @('-h', '--help', '--config')
            Values = @{ '--config' = 'file' }
            Subcommands = @('capture', 'analyze', 'full')
            Positional = $false
        }
        'diagnose_perception.py:analyze' = @{
            Options = @('-h', '--help', '--src', '--out', '--side', '--conf', '--weights', '--no-clahe')
            Values = @{ '--src' = 'file'; '--out' = 'file'; '--side' = 'choice:dashcam'; '--conf' = 'none'; '--weights' = 'file' }
            Subcommands = @()
            Positional = $false
        }
        'diagnose_perception.py:capture' = @{
            Options = @('-h', '--help', '--out', '--frames', '--spawn')
            Values = @{ '--out' = 'file'; '--frames' = 'none'; '--spawn' = 'none' }
            Subcommands = @()
            Positional = $false
        }
        'diagnose_perception.py:full' = @{
            Options = @('-h', '--help', '--src', '--out')
            Values = @{ '--src' = 'file'; '--out' = 'file' }
            Subcommands = @()
            Positional = $false
        }
        'export_engine.py' = @{
            Options = @('-h', '--help', '--config', '--weights', '--fp32')
            Values = @{ '--config' = 'file'; '--weights' = 'file' }
            Subcommands = @()
            Positional = $false
        }
        'generate_completions.py' = @{
            Options = @('-h', '--help')
            Values = @{  }
            Subcommands = @()
            Positional = $false
        }
        'offroad-autonomy' = @{
            Options = @('-h', '--help', '--config', '--weights', '--road-class', '--log-level', '--headless', '--benchmark-seconds', '--benchmark-warmup', '--benchmark-out', '--label', '--record-video', '--record-video-out', '--presentation', '--presentation-view', '--presentation-out')
            Values = @{ '--config' = 'file'; '--weights' = 'file'; '--road-class' = 'file'; '--log-level' = 'choice:DEBUG|INFO|WARNING|ERROR'; '--benchmark-seconds' = 'none'; '--benchmark-warmup' = 'none'; '--benchmark-out' = 'file'; '--label' = 'file'; '--record-video-out' = 'file'; '--presentation-out' = 'file' }
            Subcommands = @()
            Positional = $false
        }
        'sbend_sim.py' = @{
            Options = @('-h', '--help', '--config', '--radius', '--fps', '--verbose')
            Values = @{ '--config' = 'file'; '--radius' = 'none'; '--fps' = 'none' }
            Subcommands = @()
            Positional = $false
        }
    }

    $words = @()
    foreach ($element in $commandAst.CommandElements) {
        # The word under the cursor ends at the cursor; only finished words count.
        if ($element.Extent.EndOffset -lt $cursorPosition) {
            $words += $element.Extent.Text.Trim('"', "'")
        }
    }
    if ($words.Count -eq 0) {
        return
    }
    $command = Split-Path -Leaf $words[0]
    $key = $null
    $start = 1
    if ($command -eq 'offroad-autonomy' -or $command -eq 'offroad-autonomy.exe') {
        $key = 'offroad-autonomy'
    }
    elseif ($words.Count -ge 2 -and $spec.ContainsKey((Split-Path -Leaf $words[1]))) {
        $key = Split-Path -Leaf $words[1]
        $start = 2
    }
    if ($null -eq $key) {
        return
    }

    $current = $spec[$key]
    $kind = $null
    $i = $start
    while ($i -lt $words.Count) {
        $word = $words[$i]
        if ($current.Values.ContainsKey($word)) {
            if ($i + 1 -eq $words.Count) {
                $kind = $current.Values[$word]
                break
            }
            # Skip the value too, so a value spelled like a subcommand is not
            # taken for one.
            $i += 2
            continue
        }
        if ($current.Subcommands -contains $word) {
            $key = "${key}:${word}"
            $current = $spec[$key]
        }
        $i += 1
    }

    $candidates = @()
    $resultType = 'ParameterName'
    if ($null -ne $kind) {
        if (-not $kind.StartsWith('choice:')) {
            # Files are PowerShell's own fallback, and a number has no candidates.
            return
        }
        $candidates = $kind.Substring(7).Split('|')
        $resultType = 'ParameterValue'
    }
    elseif (-not $wordToComplete.StartsWith('-') -and $current.Subcommands.Count -gt 0) {
        $candidates = $current.Subcommands
        $resultType = 'ParameterValue'
    }
    elseif (-not $wordToComplete.StartsWith('-') -and $current.Positional) {
        return
    }
    else {
        $candidates = $current.Options
    }
    foreach ($candidate in $candidates) {
        if ($candidate -like "$wordToComplete*") {
            [System.Management.Automation.CompletionResult]::new(
                $candidate, $candidate, $resultType, $candidate
            )
        }
    }
}

Register-ArgumentCompleter -Native -CommandName @('offroad-autonomy', 'offroad-autonomy.exe', 'python', 'python.exe', 'python3', 'py', 'py.exe') -ScriptBlock $offroadCompleter
Remove-Variable offroadCompleter
